using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
internal sealed partial class CompanionWindow {
 QuestInstructionIndex questIndex;
 internal QuestInstructionIndex InstructionIndex {get{return questIndex??(questIndex=QuestInstructionIndex.Load(store));}}
 internal void InstructionPanel(StackPanel body,TougliStep step){if(step==null||String.IsNullOrWhiteSpace(step.QuestId)||GanymedeReader.IsGuide(DofusCompanion.Character(store.Value).guide))return;var frame=new Border{Background=Surface,CornerRadius=new CornerRadius(12),Padding=new Thickness(13),Margin=new Thickness(0,14,0,10)};var content=new StackPanel();frame.Child=content;body.Children.Add(frame);content.Children.Add(Text("INSTRUCTIONS GANYMÈDE",10));var matches=InstructionIndex.Match(step);if(matches.Count==0){content.Children.Add(Text("Aucun extrait correspondant à cette quête dans les guides chargés.",12,true));content.Children.Add(Button("Charger les instructions du parcours",LoadQuestInstructions));if(InstructionIndex.Unreadable>0)content.Children.Add(Text("Certains guides locaux n’ont pas pu être relus. Rechargez-les depuis les réglages.",10,true));return;}
 string selection=WorkspaceNext.Hash(Encoding.UTF8.GetBytes(step.QuestId+"/"+QuestInstructionIndex.NameKey(step.Title)));string chosen;store.Value.instructions.sources.TryGetValue(selection,out chosen);var sources=matches.GroupBy(x=>x.GuideSlug).ToList();if(sources.Count==1)chosen=sources[0].Key;else{var menu=Combo(new[]{"Choisir le guide pour cette quête…"}.Concat(sources.Select(g=>g.First().GuideTitle)),Math.Max(0,sources.FindIndex(g=>g.Key==chosen)+1));content.Children.Add(Text("Plusieurs guides contiennent cette quête. Choisissez celui dont vous voulez suivre les extraits.",11,true));content.Children.Add(menu);menu.SelectionChanged+=delegate{if(menu.SelectedIndex>0)Safe(()=>PersonalWorkflows.Change(store,()=>store.Value.instructions.sources[selection]=sources[menu.SelectedIndex-1].Key));};}
 var instructions=matches.Where(x=>x.GuideSlug==chosen).ToList();if(instructions.Count==0)return;string cursorKey=QuestInstructionIndex.CursorKey(store.Value,step,chosen),saved;store.Value.instructions.cursors.TryGetValue(cursorKey,out saved);int position=Math.Max(0,instructions.FindIndex(x=>x.Key==saved));var current=instructions[position];content.Children.Add(Text(current.GuideTitle+" · extrait "+(position+1)+" / "+instructions.Count,11,true));content.Children.Add(Text(current.Map+(current.Coordinates==""?"":" · ["+current.Coordinates+"]"),11));content.Children.Add(Text(current.Details,13));content.Children.Add(Text("Extrait propre à cette quête. Les trajets communs et illustrations restent dans le guide source ; l’ordre de progression reste celui de Tougli.",10,true));var controls=new WrapPanel();var previous=Button("← Instruction",()=>SetInstructionCursor(cursorKey,instructions[Math.Max(0,position-1)].Key));previous.IsEnabled=position>0;controls.Children.Add(previous);var next=Button("Instruction →",()=>SetInstructionCursor(cursorKey,instructions[Math.Min(instructions.Count-1,position+1)].Key));next.IsEnabled=position<instructions.Count-1;controls.Children.Add(next);content.Children.Add(controls);var links=new WrapPanel();if(current.Coordinates!="")links.Children.Add(Button("/travel Ganymède",()=>Clipboard.SetText("/travel "+current.Coordinates)));links.Children.Add(Button("Voir l’étape source",()=>Open(current.Url)));content.Children.Add(links);content.Children.Add(Text(current.Credit,9,true));}
 void SetInstructionCursor(string key,string value){Safe(()=>PersonalWorkflows.Change(store,()=>{var cursors=store.Value.instructions.cursors;if(!cursors.ContainsKey(key)&&cursors.Count>=5000)cursors.Remove(cursors.Keys.First());cursors[key]=value;}));}
 void LoadQuestInstructions(){if(busy)return;RunDownload(async token=>{if(cancel!=null)cancel.CancelAfter(TimeSpan.FromMinutes(8));var doc=Current();if(doc==null||GanymedeReader.IsGuide(doc.Slug))throw new InvalidOperationException("Ouvrez d’abord un parcours Tougli.");var catalogue=GanymedeReader.Catalogue(await DownloadAddress(GanymedeReader.Site+"/tree?view=list",token));if(catalogue.Count==0)throw new InvalidDataException("Aucun guide public français disponible.");int count=0,failures=0;foreach(var guide in catalogue){token.ThrowIfCancellationRequested();if(TougliReader.Cached(store,guide.Slug)==null){try{var raw=GanymedeReader.Normalise(await DownloadAddress(GanymedeReader.Url(guide.Slug),token));GanymedeReader.Parse(raw,guide.Slug);token.ThrowIfCancellationRequested();TougliReader.Cache(store,guide.Slug,raw);}catch(OperationCanceledException){throw;}catch{failures++;}}count++;message="Instructions Ganymède : "+count+" / "+catalogue.Count+" guides consultés"+(failures==0?"":" · "+failures+" indisponibles")+". Vos validations Tougli sont conservées.";questIndex=null;if(count%5==0||count==catalogue.Count)RefreshView();}questIndex=null;int covered=doc.Steps.Count(s=>InstructionIndex.Match(s).Any()),quests=doc.Steps.Count(s=>!String.IsNullOrEmpty(s.QuestId));message="Instructions disponibles pour "+covered+" / "+quests+" étapes de quête Tougli dans les guides consultés."+(failures==0?"":" "+failures+" guides indisponibles : relancez le chargement pour réessayer.");if(options!=null)BuildOptions(options);});}
}
